"use client";

import { createContext, useCallback, useContext, useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { FocusEvent, MouseEvent, PointerEvent, ReactNode, Ref } from "react";
import { MenuHighlight } from "../lib/menu-highlight";
import { SiliconLink } from "../lib/silicon-provider";
import { Badge } from "../badge/badge";
import styles from "./nav-list.module.css";

type Box = { top: number; height: number; danger: boolean; glide: boolean };
const ITEM = "[data-nav-item]";
const boxOf = (item: HTMLElement): Omit<Box, "glide"> => ({ top: item.offsetTop, height: item.offsetHeight, danger: false });

/** What NavList's onNavigate receives: the chosen row's href, or none for an action row. */
export interface NavChoice { href?: string }

/** Lets NavItem reach its list without prop drilling: the active marker's position, and reporting a choice. */
const NavContext = createContext<{ activeChanged: () => void; navigate: (choice: NavChoice) => void } | null>(null);

export interface NavListProps {
  /** Names the navigation for screen readers, such as "Main" or "Settings". */
  label: string;
  /** NavItem and NavSection elements, in order. */
  children: ReactNode;
  /** Placement only (width, margins, grid area); the rows' look comes from the component. */
  className?: string;
  /** The `<nav>` element. */
  ref?: Ref<HTMLElement>;
  /**
   * Called when any row is chosen (click, Enter or Space; link and action rows), before it navigates or acts. A notification,
   * such as closing a phone sheet: it cannot cancel. Locked rows and modified clicks (a new tab or window) do not call it.
   */
  onNavigate?: (choice: NavChoice) => void;
}

/**
 * A sidebar's list of destinations: a `<nav>` with a list of NavItem rows, optionally grouped by NavSection. One hover highlight
 * glides between rows for the pointer, and the current page's marker glides when the page changes.
 */
export function NavList({ label, children, className, ref, onNavigate }: NavListProps) {
  const root = useRef<HTMLElement | null>(null);
  const [hover, setHover] = useState<Box | null>(null);
  const [active, setActive] = useState<Box | null>(null);
  const pointer = useRef(false);
  // The latest handler, read at choice time, so a new function each render never changes the context.
  const navigateHandler = useRef(onNavigate);
  useEffect(() => { navigateHandler.current = onNavigate; });

  const setRoot = useCallback((node: HTMLElement | null) => {
    root.current = node;
    if (typeof ref === "function") return ref(node);
    if (ref) ref.current = node;
  }, [ref]);

  // The active marker follows the item with aria-current. It glides only when the page changes, never on first paint.
  const measureActive = useCallback(() => {
    const item = root.current?.querySelector<HTMLElement>(`${ITEM}[aria-current="page"]`);
    setActive(current => {
      if (!item) return null;
      const next = boxOf(item);
      return current && current.top === next.top && current.height === next.height ? current : { ...next, glide: current !== null };
    });
  }, []);
  useLayoutEffect(() => {
    measureActive();
    const node = root.current;
    if (!node || typeof ResizeObserver === "undefined") return;
    // A resize (a late font, a collapsing section) moves the marker at once; only a page change glides.
    const observer = new ResizeObserver(() => {
      const item = node.querySelector<HTMLElement>(`${ITEM}[aria-current="page"]`);
      setActive(current => {
        if (!item) return null;
        const next = boxOf(item);
        return current && current.top === next.top && current.height === next.height ? current : { ...next, glide: false };
      });
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, [measureActive]);

  function show(target: EventTarget | null, glide: boolean) {
    const item = target instanceof HTMLElement ? target.closest<HTMLElement>(ITEM) : null;
    if (!item || item.getAttribute("aria-disabled") === "true") return setHover(null);
    setHover(current => ({ ...boxOf(item), glide: glide && current !== null }));
  }

  const context = useMemo(() => ({ activeChanged: measureActive, navigate: (choice: NavChoice) => navigateHandler.current?.(choice) }), [measureActive]);
  return (
    <NavContext.Provider value={context}>
      <nav ref={setRoot} aria-label={label} className={[styles.list, className].filter(Boolean).join(" ")}
        onPointerOver={(event: PointerEvent<HTMLElement>) => { pointer.current = true; show(event.target, true); }}
        onPointerLeave={() => setHover(null)}
        onKeyDownCapture={() => { pointer.current = false; }}
        onFocus={(event: FocusEvent<HTMLElement>) => { if (!pointer.current && event.target.matches(":focus-visible")) show(event.target, false); }}
        onBlur={(event: FocusEvent<HTMLElement>) => { if (!pointer.current && !event.currentTarget.contains(event.relatedTarget as Node | null)) setHover(null); }}>
        {/* The current page's marker paints over the hover fill, so hovering the current row never lightens it. */}
        <MenuHighlight state={hover} className={styles.highlight} />
        <MenuHighlight state={active} className={styles.active} />
        <ul className={styles.items}>{children}</ul>
      </nav>
    </NavContext.Provider>
  );
}

export interface NavSectionProps {
  /** The section's heading, such as "Workspace". */
  label: string;
  /** The section's NavItem rows. */
  children: ReactNode;
}

/** A labelled group of NavItem rows inside a NavList. */
export function NavSection({ label, children }: NavSectionProps) {
  const id = useId();
  return (
    <li className={styles.section}>
      <div id={id} className={styles.sectionLabel}>{label}</div>
      <ul className={styles.items} aria-labelledby={id}>{children}</ul>
    </li>
  );
}

interface NavItemBase {
  /** The row's label. */
  children: ReactNode;
  /** A 16px icon before the label. */
  icon?: ReactNode;
  /** The current page: sets aria-current="page" and the active marker. */
  active?: boolean;
  /** Turns the row off. It stays focusable (aria-disabled) so keyboard users can reach it and hear why. */
  disabled?: boolean;
  /** Why the row is off, such as "Pro". Shown as a badge and read as the row's description. Only shown when disabled. */
  reason?: string;
  /** Content at the row's end, such as a count or an avatar. Hidden while a reason shows. */
  trailing?: ReactNode;
  /**
   * Called each time the pointer enters the row or it receives focus, before it is chosen: start loading the destination
   * (prefetch). It can fire more than once, so keep it idempotent. Not called while disabled.
   */
  onIntent?: () => void;
  /** Placement only; the row's look comes from the component. */
  className?: string;
}

export type NavItemProps = NavItemBase & (
  | { /** A destination, rendered with the SiliconProvider's link. */ href: string; onSelect?: never }
  | { href?: never; /** An action, such as opening search. */ onSelect: () => void }
);

/** One row of a NavList: a link by `href`, or an action by `onSelect`. */
export function NavItem({ children, icon, active = false, disabled = false, reason, trailing, onIntent, className, href, onSelect }: NavItemProps) {
  const nav = useContext(NavContext);
  const reasonId = useId();
  const showReason = disabled && reason;
  useLayoutEffect(() => { nav?.activeChanged(); }, [active, nav]);

  const content = <>
    {icon ? <span className={styles.icon} aria-hidden="true">{icon}</span> : null}
    <span className={styles.label}>{children}</span>
    {/* Hidden from the name and read once, as the description (aria-describedby reads hidden text). */}
    {showReason ? <Badge id={reasonId} size="sm" className={styles.reason} aria-hidden="true">{reason}</Badge>
      : trailing ? <span className={styles.trailing}>{trailing}</span> : null}
  </>;
  const shared = {
    className: [styles.item, className].filter(Boolean).join(" "),
    "data-nav-item": "",
    "aria-current": active ? "page" as const : undefined,
    "aria-disabled": disabled || undefined,
    "aria-describedby": showReason ? reasonId : undefined,
  };

  if (disabled) {
    // No href and no action: it can be focused and read, but not followed.
    return <li><span {...shared} role={href ? "link" : "button"} tabIndex={0} onClick={(event: MouseEvent<HTMLElement>) => event.preventDefault()}>{content}</span></li>;
  }
  const intent = onIntent ? { onPointerEnter: onIntent, onFocus: onIntent } : {};
  if (href !== undefined) {
    // A modified click opens a new tab or window, so this page stays where it is: no choice to report.
    const onClick = (event: MouseEvent<HTMLAnchorElement>) => { if (event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey) nav?.navigate({ href }); };
    return <li><SiliconLink {...shared} {...intent} href={href} onClick={onClick}>{content}</SiliconLink></li>;
  }
  return <li><button {...shared} {...intent} type="button" onClick={() => { nav?.navigate({}); onSelect?.(); }}>{content}</button></li>;
}

export default NavList;

/* The list is the positioning box for both markers, so rows measure their offsetTop against it. Place it on --background or
   --surface; on a --surface-muted panel the hover fill has nothing to show against. */
.list { position: relative; display: block; font-family: var(--font-body); letter-spacing: var(--tracking-body); }
.items { display: grid; gap: var(--space-hair); margin: 0; padding: 0; list-style: none; }
.section + .section, .items > li + .section { margin-top: var(--space-group); }
.sectionLabel { padding: var(--space-tight) var(--space-related); color: var(--text-muted); font-size: var(--text-xs); font-weight: 500; line-height: var(--leading-body); }

/* Two markers under the rows: the current page (stronger), and the pointer's hover, which glides between rows. */
.active, .highlight { position: absolute; top: 0; right: 0; left: 0; border-radius: var(--radius-control); corner-shape: var(--corner-shape); pointer-events: none; }
.active { background: var(--surface-pressed); }
.highlight { background: var(--surface-muted); }

.item { position: relative; display: flex; box-sizing: border-box; width: 100%; min-height: 2rem; align-items: center; gap: var(--space-related); margin: 0; padding: 0 var(--space-related); border: 0; border-radius: var(--radius-control); corner-shape: var(--corner-shape); background: transparent; color: var(--text-secondary); font: inherit; font-size: var(--text-sm); line-height: var(--leading-body); text-align: left; text-decoration: none; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: color var(--duration-fast) var(--ease-standard); }
.item:hover, .item:focus-visible, .item[aria-current="page"] { color: var(--foreground); }
.item[aria-current="page"] { font-weight: 500; }
.item[aria-disabled="true"] { color: var(--text-muted); cursor: not-allowed; }
.icon { display: inline-flex; flex: none; color: var(--text-secondary); }
.icon svg { width: 16px; height: 16px; }
.item[aria-current="page"] .icon, .item:hover .icon { color: var(--foreground); }
.item[aria-disabled="true"] .icon { color: var(--text-muted); }
.label { min-width: 0; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.trailing { display: inline-flex; flex: none; align-items: center; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.reason { flex: none; }

@media (prefers-reduced-motion: reduce) { .item { transition: none; } }

"use client";

import { useEffect, useRef, useState } from "react";
import type { FocusEvent } from "react";
import { motion, useReducedMotion } from "motion/react";
import { motionTokens } from "./motion-tokens";

type Highlight = { top: number; height: number; danger: boolean; glide: boolean };

/**
 * One highlight that glides between the items of a Radix menu or listbox for the pointer, and jumps instantly for the keyboard.
 * Radix focuses the highlighted item, so the highlight follows focus inside the content. Spread `contentProps` on the content,
 * call `reset` when it opens, and render `<MenuHighlight state={highlight} className={styles.highlight} />` as its first child.
 * Items mark a destructive tone with `data-tone="danger"`.
 */
export function useMenuHighlight(itemSelector = '[role="menuitem"], [role="option"]') {
  const [highlight, setHighlight] = useState<Highlight | null>(null);
  const pointer = useRef(false);
  const clearTimer = useRef(0);
  useEffect(() => () => window.clearTimeout(clearTimer.current), []);

  function onFocus(event: FocusEvent<HTMLElement>) {
    const item = event.target instanceof HTMLElement ? event.target.closest<HTMLElement>(itemSelector) : null;
    window.clearTimeout(clearTimer.current);
    if (!item) {
      // A short grace period keeps the highlight gliding across separators and item gaps.
      clearTimer.current = window.setTimeout(() => setHighlight(null), pointer.current ? 70 : 0);
      return;
    }
    const next = { top: item.offsetTop, height: item.offsetHeight, danger: item.dataset.tone === "danger" };
    const glide = pointer.current;
    setHighlight(current => ({ ...next, glide: glide && current !== null }));
  }

  return {
    highlight,
    reset: () => { window.clearTimeout(clearTimer.current); setHighlight(null); },
    contentProps: {
      onFocus,
      onPointerMoveCapture: () => { pointer.current = true; },
      onKeyDownCapture: () => { pointer.current = false; },
    },
  };
}

/** The gliding highlight itself. Position it absolutely inside the content, under the items. */
export function MenuHighlight({ state, className }: { state: Highlight | null; className?: string }) {
  const reduced = useReducedMotion();
  return <motion.span className={className} data-tone={state?.danger ? "danger" : undefined} aria-hidden="true" initial={false}
    animate={state ? { y: state.top, height: state.height, opacity: 1 } : { opacity: 0 }}
    transition={{ default: state?.glide && !reduced ? motionTokens.spring.snappy : { duration: 0 }, opacity: { duration: reduced ? 0 : .08 } }} />;
}

"use client";

/**
 * Lets an app swap the link and image elements Silicon UI components render.
 *
 * Without a provider, Silicon UI renders a plain `<a>` and `<img>`, so components work in any React app (Vite, Remix, Astro,
 * plain React). Wrap the app once to use your framework's or your own components instead:
 *
 *   import Link from "next/link";
 *   import Image from "next/image";
 *   import { SiliconProvider } from "@/components/silicon-ui/lib/silicon-provider";
 *
 *   <SiliconProvider link={Link} image={Image}>{children}</SiliconProvider>
 *
 * Any component that accepts these props works, such as a locale-aware Link from next-intl or a React Router Link
 * wrapped to map `href` to `to`.
 */
import { createContext, createElement, useContext, useMemo, type AnchorHTMLAttributes, type ComponentType, type ImgHTMLAttributes, type ReactNode, type Ref } from "react";

/** The props Silicon UI passes to a link: an href plus ordinary anchor attributes. */
export interface SiliconLinkProps extends AnchorHTMLAttributes<HTMLAnchorElement> {
  href: string;
  ref?: Ref<HTMLAnchorElement>;
}

/**
 * The props Silicon UI passes to an image. A subset of next/image's props, so next/image can be passed as is: either `fill`
 * (cover the positioned parent) or `width` and `height`, plus `sizes` and `priority` as hints.
 */
export interface SiliconImageProps extends Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "alt" | "width" | "height" | "loading" | "srcSet"> {
  src: string;
  alt: string;
  width?: number;
  height?: number;
  /** Fills the nearest positioned parent, like next/image's `fill`. */
  fill?: boolean;
  /** Loads the image eagerly with high priority, like next/image's `priority`. */
  priority?: boolean;
  loading?: "eager" | "lazy";
  ref?: Ref<HTMLImageElement>;
}

export type SiliconLinkComponent = ComponentType<SiliconLinkProps>;
export type SiliconImageComponent = ComponentType<SiliconImageProps>;

/** The default link: a plain anchor. */
export function SiliconAnchor(props: SiliconLinkProps) {
  return <a {...props} />;
}

const fillStyle = { position: "absolute", inset: 0, width: "100%", height: "100%" } as const;

/** The default image: a plain, lazily decoded `<img>` that understands `fill` and `priority`. */
export function SiliconImg({ alt, fill, priority, loading, style, ...props }: SiliconImageProps) {
  // eslint-disable-next-line @next/next/no-img-element -- the framework-free default; pass next/image through SiliconProvider instead.
  return <img alt={alt} decoding="async" {...props} loading={loading ?? (priority ? "eager" : "lazy")} fetchPriority={priority ? "high" : props.fetchPriority} style={fill ? { ...fillStyle, ...style } : style} />;
}

interface SiliconComponents {
  link: SiliconLinkComponent;
  image: SiliconImageComponent;
}

const SiliconContext = createContext<SiliconComponents>({ link: SiliconAnchor, image: SiliconImg });

export interface SiliconProviderProps {
  /** The link component Silicon UI renders for navigation, such as next/link or your own wrapped Link. Defaults to `<a>`. */
  link?: SiliconLinkComponent;
  /** The image component Silicon UI renders for photos, such as next/image. Defaults to `<img>`. */
  image?: SiliconImageComponent;
  children: ReactNode;
}

/** Sets the link and image components for every Silicon UI component inside it. Nested providers inherit what they do not set. */
export function SiliconProvider({ link, image, children }: SiliconProviderProps) {
  const parent = useContext(SiliconContext);
  const value = useMemo(() => ({ link: link ?? parent.link, image: image ?? parent.image }), [link, image, parent]);
  return <SiliconContext.Provider value={value}>{children}</SiliconContext.Provider>;
}

/** The link component from the nearest SiliconProvider, or a plain anchor. */
export const useArcLink = () => useContext(SiliconContext).link;
/** The image component from the nearest SiliconProvider, or a plain img. */
export const useArcImage = () => useContext(SiliconContext).image;

/** What Silicon UI components render for a link: the provider's link component, or a plain anchor. */
export function SiliconLink(props: SiliconLinkProps) {
  return createElement(useArcLink(), props);
}

/** What Silicon UI components render for an image: the provider's image component, or a plain img. */
export function SiliconImage(props: SiliconImageProps) {
  return createElement(useArcImage(), props);
}
